window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-285ae75529e263aa"]={"versions": [{"id": "FIG-285ae75529e263aa", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Metamodell- bzw. SWC-Strukturdiagramm (Komponentenmodell) zur Veranschaulichung des Wiederverwendungsprinzips von <code>PortInterface</code>-Definitionen an Ports variantenabhängiger <code>ComponentPrototype</code>-Instanzen desselben <code>AtomicSoftwareComponentType</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt folgende Modell-Elemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AtomicSoftwareComponent</code> (Typ-Ebene): <code>EngineControl</code> als Definitionsgrundlage für Software-Komponenten-Instanzen.\n</li><li><code>ComponentPrototype</code> (Instanz-/Prototyp-Ebene): Zwei Ausprägungen desselben Komponenten-Typs:\n<ul class=\"fig-list\"><li><code>EngineControl (gasoline variant)</code> mit zwei <code>PPort</code>-Elementen: <code>TorqueInterventionFast</code> und <code>TorqueInterventionSlow</code>.\n</li><li><code>EngineControl (diesel variant)</code> mit einem <code>PPort</code>-Element: <code>TorqueInterventionFast</code>.\n</li></ul>\n</li><li><code>PortInterface</code>: <code>TorqueIntervention1</code>, das per Assoziation (gepunktete Linien) von allen drei <code>PPort</code>-Instanzen typisierend wiederverwendet wird.\n</li><li>Gekoppelte Zuordnungen (gepunktete Linien): Beide <code>ComponentPrototype</code>-Instanzen referenzieren den gemeinsamen Typ <code>EngineControl</code>; alle <code>PPort</code>-Instanzen beider Varianten referenzieren dasselbe Interface <code>TorqueIntervention1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklarationsübersicht ohne Laufzeit- oder Sequenzinteraktion. Dargestellt wird die strukturelle Typisierung und Zuordnung von Bereitstellungs-Ports (<code>PPort</code>) zu einem vereinheitlichten Schnittstellenvertrag (<code>TorqueIntervention1</code>) über alternative Ausprägungsvarianten (Benzin vs. Diesel) hinweg.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>PortInterface-Wiederverwendung</strong>: Identische semantische Schnittstellenbeschreibungen (hier Drehmomenteingriff) sollen als gemeinsames <code>PortInterface</code> modelliert und portübergreifend wiederverwendet werden, anstatt redundante Schnittstellentypen anzulegen.\n</li><li><strong>Variantenmodellierung</strong>: Varianten eines Komponenten-Typs können unterschiedliche Port-Mengen aufweisen (z. B. zusätzliche Ports für spezifische Subsysteme wie <code>TorqueInterventionSlow</code> bei Benzinmotoren).\n</li><li><strong>Namenskonventionen</strong>: Werden gleichnamige Ports oder Schnittstellen über mehrere Komponentenprototypen hinweg angebunden, sind standardisierte Namensbildungsregeln einzuhalten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-df1d0def1071d577", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Metamodell- bzw. SWC-Strukturdiagramm (Komponentenmodell) zur Veranschaulichung des Wiederverwendungsprinzips von <code>PortInterface</code>-Definitionen an Ports variantenabhängiger <code>ComponentPrototype</code>-Instanzen desselben <code>AtomicSoftwareComponentType</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt folgende Modell-Elemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AtomicSoftwareComponent</code> (Typ-Ebene): <code>EngineControl</code> als Definitionsgrundlage für Software-Komponenten-Instanzen.\n</li><li><code>ComponentPrototype</code> (Instanz-/Prototyp-Ebene): Zwei Ausprägungen desselben Komponenten-Typs:\n<ul class=\"fig-list\"><li><code>EngineControl (gasoline variant)</code> mit zwei <code>PPort</code>-Elementen: <code>TorqueInterventionFast</code> und <code>TorqueInterventionSlow</code>.\n</li><li><code>EngineControl (diesel variant)</code> mit einem <code>PPort</code>-Element: <code>TorqueInterventionFast</code>.\n</li></ul>\n</li><li><code>PortInterface</code>: <code>TorqueIntervention1</code>, das per Assoziation (gepunktete Linien) von allen drei <code>PPort</code>-Instanzen typisierend wiederverwendet wird.\n</li><li>Gekoppelte Zuordnungen (gepunktete Linien): Beide <code>ComponentPrototype</code>-Instanzen referenzieren den gemeinsamen Typ <code>EngineControl</code>; alle <code>PPort</code>-Instanzen beider Varianten referenzieren dasselbe Interface <code>TorqueIntervention1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Deklarationsübersicht ohne Laufzeit- oder Sequenzinteraktion. Dargestellt wird die strukturelle Typisierung und Zuordnung von Bereitstellungs-Ports (<code>PPort</code>) zu einem vereinheitlichten Schnittstellenvertrag (<code>TorqueIntervention1</code>) über alternative Ausprägungsvarianten (Benzin vs. Diesel) hinweg.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>PortInterface-Wiederverwendung</strong>: Identische semantische Schnittstellenbeschreibungen (hier Drehmomenteingriff) sollen als gemeinsames <code>PortInterface</code> modelliert und portübergreifend wiederverwendet werden, anstatt redundante Schnittstellentypen anzulegen.\n</li><li><strong>Variantenmodellierung</strong>: Varianten eines Komponenten-Typs können unterschiedliche Port-Mengen aufweisen (z. B. zusätzliche Ports für spezifische Subsysteme wie <code>TorqueInterventionSlow</code> bei Benzinmotoren).\n</li><li><strong>Namenskonventionen</strong>: Werden gleichnamige Ports oder Schnittstellen über mehrere Komponentenprototypen hinweg angebunden, sind standardisierte Namensbildungsregeln einzuhalten.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-285ae75529e263aa", "to": "FIG-df1d0def1071d577", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
